#[repr(C, align(64))]
#[derive(Clone, Copy)]
struct numa_drop_counters {
    drops0: __SlateRecord_types_h_190,
    __slate_pad_1: [u8; 60],
    drops1: __SlateRecord_types_h_190,
}


fn numa_drop_add(ndc: *mut numa_drop_counters, val: i32) {
let n: i32 = numa_node_id() % 2;
if n != 0 {
atomic_add(val, unsafe { core::ptr::addr_of_mut!((*ndc).drops1) });
} else {
atomic_add(val, unsafe { core::ptr::addr_of_mut!((*ndc).drops0) });
}
}

// dev_addrs walker. Should be used only for read access. Call with
// rcu_read_lock held.
// The list of packet types we will receive (as opposed to discard)
// and the routines to invoke.
//
// Why 16. Because with 16 the only overlap we get on a hash of the
// low nibble of the protocol value is RARP/SNAP/X.25.
//
// 	0800	IP
// 	0001	802.3
// 	0002	AX.25
// 	0004	802.2
// 	8035	RARP
// 	0005	SNAP
// 	0805	X.25
// 	0806	ARP
// 	8137	IPX
// 	0009	Localtalk
// 	86DD	IPv6
// Note: Avoid these macros in fast path, prefer per-cpu or per-queue counters.
